          <tr><td><strong>Air Jordan 1 Low</strong></td><td>1,020</td><td>$125.36</td><td>$175.88</td><td class="positive">$50.52</td><td>59.7%</td><td>23.1</td></tr>
        </tbody>
      </table>
    </div>
    <div class="card">
      <h3>Model Profit Comparison</h3>
