          <tr><td><strong>Concord</strong></td><td>547</td><td>$272.06</td><td class="positive">$80.85</td><td>61.8%</td></tr>
          <tr><td><strong>Bred</strong></td><td>542</td><td>$267.43</td><td class="positive">$76.55</td><td>61.6%</td></tr>
